stop();
_root.gametime = _root.maxtime;
time = function()
{
   if(_root.zhanting == false)
   {
      if(_root.game.p1.mc.sw == false and _root.game.p2.mc.sw == false)
      {
         if(_root.modo != 4)
         {
            _root.gametime -= 1;
         }
      }
   }
   tm = _root.gametime;
   if(tm <= 0)
   {
      if(_root.timeover.played == 0)
      {
         _root.to = true;
         _root.timeover.play();
         played = 1;
      }
      tm = 0;
   }
   else
   {
      _root.to = false;
   }
   if(tm >= 10)
   {
      shi = Math.floor(tm / 10);
      gs = tm - shi * 10;
   }
   if(tm < 10)
   {
      shi = 0;
      gs = tm;
   }
   十.gotoAndStop(shi + 1);
   个.gotoAndStop(gs + 1);
};
if(_root.maxtime == 100 or _root.modo == 4)
{
   gotoAndStop("无限时");
}
else
{
   _root.timeset = setInterval(time,1000);
}

p1head.namemc.gotoAndStop(_root.p1selt);
p2head.namemc.gotoAndStop(_root.p2selt);
var p1hp;
var p2hp;
var bar2Spd = _root.maxhp / 500;
onEnterFrame = function()
{
   p1hp = _root.game.p1.mc.hp / _root.maxhp * 100;
   p2hp = _root.game.p2.mc.hp / _root.maxhp * 100;
   p1xt.bar._xscale = p1hp;
   p2xt.bar._xscale = p2hp;
   if(p1hp <= 0 || p2hp <= 0)
   {
      return undefined;
   }
   if(p1xt.bar._xscale < 20)
   {
      p1xt.kk.gotoAndStop(2);
      _root.game.p1.mc.ql += 0.2;
   }
   if(p2xt.bar._xscale < 20)
   {
      p2xt.kk.gotoAndStop(2);
      _root.game.p2.mc.ql += 0.2;
   }
   var _loc2_ = _root.game.p2.mc.hits;
   var _loc3_ = _root.game.p1.mc.hits;
   if(_loc3_ == 0)
   {
      if(p1xt.bar2._xscale > p1hp)
      {
         p1xt.bar2._xscale -= bar2Spd;
      }
      else
      {
         p1xt.bar2._xscale = p1hp;
      }
   }
   if(_loc2_ == 0)
   {
      if(p2xt.bar2._xscale > p2hp)
      {
         p2xt.bar2._xscale -= bar2Spd;
      }
      else
      {
         p2xt.bar2._xscale = p2hp;
      }
   }
};
_root.xuntiaoInitlize = function()
{
   p1xt.bar._xscale = 100;
   p1xt.bar2._xscale = 100;
   p2xt.bar._xscale = 100;
   p2xt.bar2._xscale = 100;
   p1xt.kk.gotoAndStop(1);
   p2xt.kk.gotoAndStop(1);
};
_root.updateWins = function()
{
   trace("updateWins");
   p1xt.win.gotoAndStop(_root.p1ws);
   p2xt.win.gotoAndStop(_root.p2ws);
};
